#!/usr/bin/env bash
# FIRONOVA - patch: confirmation automatique Interac (Autodeposit) via Microsoft Graph
# Remplace backend/server.py (backup auto), ajoute backend/dryrun_interac.py, puis restart.
# Usage (sur le serveur, depuis /app):
#   bash apply_interac.sh && sudo supervisorctl restart all
set -euo pipefail
cd "$(dirname "$0")"
F="backend/server.py"
D="backend/dryrun_interac.py"
[ -f "$F" ] || { echo "ERREUR: lance depuis /app"; exit 1; }
TS=$(date +%Y%m%d-%H%M%S)
cp "$F" "$F.bak-interac-$TS"
echo "Backup cree: $F.bak-interac-$TS"
cat > /tmp/_fn_interac.b64 << 'FN_B64_END'

FN_B64_END
base64 -d /tmp/_fn_interac.b64 > "$F"
rm -f /tmp/_fn_interac.b64
cat > "$D" << 'FN_DRY_END'

FN_DRY_END
python3 -c "import ast; ast.parse(open('$F', encoding='utf-8').read()); ast.parse(open('$D', encoding='utf-8').read()); print('Syntax OK')"
echo "OK: backend/server.py + backend/dryrun_interac.py en place (version Interac Graph)."
echo "Etapes suivantes:"
echo "  1) cd backend && python3 dryrun_interac.py   # validation lecture seule du Graph"
echo "  2) cd .. && sudo supervisorctl restart all"